var _markdown = "\n\n`CMenuManager.h` · 全局 `FrontEndMenuManager`\n\n暂停菜单、偏好、是否在前端。逻辑帧里常用来判断「能不能动游戏」。\n\n## 菜单是否打开 [#菜单是否打开]\n\n<Api name=\"m_bMenuActive / m_bSaveMenuActive\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      bool m_bMenuActive;\n      bool m_bSaveMenuActive;\n      bool m_bGameNotLoaded;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      if (FrontEndMenuManager.m_bMenuActive) {\n          return; // 暂停菜单打开时跳过作弊处理\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 请求开关前端 [#请求开关前端]\n\n<Api name=\"m_bStartUpFrontEndRequested / m_bExitMenu\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      bool m_bStartUpFrontEndRequested;\n      bool m_bShutDownFrontEndRequested;\n      bool m_bExitMenu;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 一般只读；强行改可能卡菜单状态机\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 常用偏好 [#常用偏好]\n\n<Api name=\"m_bPrefsShowHud / m_bPrefsShowSubtitles\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      bool m_bPrefsShowHud;\n      bool m_bPrefsShowSubtitles;\n      bool m_bPrefsUseWideScreen;\n      bool m_bPrefsVsync;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      bool showHud = FrontEndMenuManager.m_bPrefsShowHud;\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 地图图例偏好 [#地图图例偏好]\n\n<Api name=\"m_bPrefsShowLocations / Contacts / Mission\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      bool m_bPrefsShowLocations;\n      bool m_bPrefsShowContacts;\n      bool m_bPrefsShowMission;\n      bool m_bPrefsShowOther;\n      bool m_bPrefsShowGangArea;\n      bool m_bPrefsShowLegends;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 雷达/地图过滤相关\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 重启与读档意图 [#重启与读档意图]\n\n<Api name=\"m_bWantToRestart / m_bWantToLoad\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      bool m_bWantToRestart;\n      bool m_bWantToLoad;\n      bool m_bOnlySaveMenu;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 监听读档/重启时清自己的运行时状态\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 静态杂项 [#静态杂项]\n\n<Api name=\"nLastMenuPage / bInvertMouseX\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static int& nLastMenuPage;\n      static bool& bInvertMouseX;\n      static bool& bInvertMouseY;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      int page = CMenuManager::nLastMenuPage;\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n";
